cat > src/emails/welcome.tsx <<'EOF'
export function WelcomeEmail({ name, appUrl }: { name: string; appUrl: string }) {
  return (
    <div>
      <h1>Welcome to Notely, {name}!</h1>
      <p>Your account is ready. Start taking notes any time.</p>
      <p>
        <a href={`${appUrl}/dashboard`}>Open your dashboard</a>
      </p>
    </div>
  );
}
EOF
cat > src/emails/password-reset.tsx <<'EOF'
export function PasswordResetEmail({ name, actionUrl }: { name: string; actionUrl: string }) {
  return (
    <div>
      <h1>Reset your password</h1>
      <p>Hi {name}, we received a request to reset your Notely password.</p>
      <p>
        <a href={actionUrl}>Choose a new password</a>
      </p>
      <p>If you didn&apos;t ask for this, you can ignore this email.</p>
    </div>
  );
}
EOF
cat > src/lib/email.ts <<'EOF'
import { PasswordResetEmail } from "@/emails/password-reset";
import { WelcomeEmail } from "@/emails/welcome";
import { resend } from "@/lib/resend";
import type { User } from "@/lib/users";

const appUrl = () => process.env.APP_URL ?? "http://localhost:3000";

// Resend resolves to { error } instead of throwing; log it so a failed email
// never breaks the request that triggered it.
async function send(options: Parameters<typeof resend.emails.send>[0]) {
  try {
    const { error } = await resend.emails.send(options);
    if (error) console.error(`Email "${options.subject}" failed: ${error.name}: ${error.message}`);
  } catch (err) {
    console.error(`Email "${options.subject}" failed`, err);
  }
}

export function sendWelcomeEmail(user: User) {
  return send({
    from: process.env.RESEND_FROM_EMAIL!,
    to: user.email,
    subject: "Welcome to Notely",
    react: WelcomeEmail({ name: user.name, appUrl: appUrl() }),
  });
}

export function sendPasswordResetEmail(user: User, token: string) {
  const actionUrl = `${appUrl()}/reset-password?token=${encodeURIComponent(token)}`;
  return send({
    from: process.env.RESEND_FROM_EMAIL!,
    to: user.email,
    subject: "Reset your Notely password",
    react: PasswordResetEmail({ name: user.name, actionUrl }),
  });
}
EOF
cat >> src/lib/users.ts <<'EOF'

export async function createUser(input: { email: string; name: string }): Promise<User> {
  const email = input.email.trim().toLowerCase();
  if (users.some((u) => u.email === email)) throw new Error("Email already registered");
  const user: User = {
    id: String(users.length + 1),
    email,
    name: input.name.trim(),
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  await sendWelcomeEmail(user);
  return user;
}

// TODO: persist tokens (hashed, with expiry) once there is a database; the reset
// page that consumes the token doesn't exist yet either.
export async function requestPasswordReset(email: string): Promise<void> {
  const user = users.find((u) => u.email === email.trim().toLowerCase());
  // Unknown addresses return silently so callers can't probe which emails exist.
  if (!user) return;
  await sendPasswordResetEmail(user, randomBytes(32).toString("hex"));
}
EOF
